<template>
  <div class="detail-page" v-loading="loading">
    <div class="detail-head"><div><el-button text @click="router.back()">返回</el-button><p class="eyebrow">{{ order?.order_no }}</p><h1>{{ order?.temporary_customer_name || `客户 ${order?.customer_id || '-'}` }} <el-tag v-if="order" :type="order.order_type === 'sample' ? 'warning' : 'success'">{{ order.order_type === 'sample' ? '样件' : '正式' }}</el-tag></h1><p class="subhead">PO：{{ order?.po_no || '样件无 PO' }} · 最后修改 {{ formatDate(order?.last_modified_at) }}</p></div><div class="head-actions"><el-button v-if="order?.status === 'draft'" @click="router.push(`/shipping-orders?edit=${order.id}`)">编辑草稿</el-button><el-button v-if="order?.status === 'draft'" type="primary" @click="submit">提交订单</el-button></div></div>
    <el-alert v-if="order?.status === 'draft'" title="草稿仅创建人可见，可继续修改。提交后订单明细将锁定。" type="info" show-icon :closable="false" />
    <section class="section"><div class="section-title"><h2>订单明细</h2><span>{{ order?.lines?.length || 0 }} 行</span></div><el-table :data="order?.lines || []" stripe><el-table-column prop="customer_part_no_snapshot" label="客户件号" min-width="170" /><el-table-column prop="part_name_snapshot" label="零件名称" min-width="180" /><el-table-column prop="ordered_qty" label="订单数量" width="100" align="right" /><el-table-column prop="planned_ship_date" label="计划发货日" width="130" /><el-table-column label="已发 / 剩余" width="125"><template #default="{ row }">{{ row.shipped_qty }} / {{ row.remaining_qty }}</template></el-table-column><el-table-column label="状态" width="150"><template #default="{ row }"><el-tag size="small" :type="lineType(row.status)">{{ lineLabel(row.status) }}</el-tag><div v-if="pendingConsent(row)" class="consent-hint">待双方确认取消</div><div v-else-if="latestConsent(row)?.status === 'rejected'" class="consent-hint rejected">取消申请已拒绝</div></template></el-table-column><el-table-column label="操作" width="240" fixed="right"><template #default="{ row }"><el-button v-if="!row.label_confirmed && order?.status !== 'draft'" link type="success" @click="labelConfirm(row)">标签确认</el-button><el-button v-if="pendingConsent(row)" link type="warning" @click="respondCancellation(row, true)">确认取消</el-button><el-button v-if="pendingConsent(row)" link type="info" @click="respondCancellation(row, false)">拒绝取消</el-button><el-button v-if="order?.status !== 'draft' && row.remaining_qty > 0 && row.status !== 'cancelled' && !pendingConsent(row)" link type="danger" @click="cancel(row)">取消剩余</el-button></template></el-table-column></el-table></section>
    <section v-if="order?.shipments?.length" class="section"><div class="section-title"><h2>发货记录</h2><span>{{ order.shipments.length }} 次</span></div><el-table :data="order.shipments" stripe><el-table-column prop="shipment_no" label="发货单号" min-width="180" /><el-table-column label="数量" min-width="180"><template #default="{ row }">{{ row.lines?.map((line: any) => `${line.qty} 件`).join('、') }}</template></el-table-column><el-table-column label="物流" min-width="240"><template #default="{ row }"><div v-for="item in row.logistics" :key="item.id">{{ item.carrier_name || '-' }} · {{ item.tracking_no || '-' }}</div></template></el-table-column><el-table-column prop="production_batch_no" label="生产批次（预留）" min-width="150" /><el-table-column prop="confirmed_at" label="确认时间" min-width="170"><template #default="{ row }">{{ formatDate(row.confirmed_at) }}</template></el-table-column><el-table-column label="操作" width="110"><template #default="{ row }"><el-button link type="primary" @click="editLogistics(row)">修改物流</el-button></template></el-table-column></el-table></section>
    <section v-if="history.length" class="section"><div class="section-title"><h2>操作历史</h2><span>{{ history.length }} 条</span></div><el-table :data="history" stripe><el-table-column prop="created_at" label="时间" min-width="175"><template #default="{ row }">{{ formatDate(row.created_at) }}</template></el-table-column><el-table-column prop="action" label="动作" width="100" /><el-table-column prop="entity_type" label="对象" min-width="210" /><el-table-column prop="changes_summary" label="说明" min-width="240" /></el-table></section>
    <el-dialog v-model="logisticsVisible" title="修改物流信息" width="620px"><div v-for="(item, index) in logisticsEdit" :key="index" class="logistics-edit-row"><el-input v-model="item.carrier_name" placeholder="物流公司" /><el-input v-model="item.tracking_no" placeholder="物流号" /><el-button text type="danger" @click="logisticsEdit.splice(index, 1)">删除</el-button></div><el-button link type="primary" @click="logisticsEdit.push({ carrier_name: '', tracking_no: '' })">新增物流行</el-button><template #footer><el-button @click="logisticsVisible = false">取消</el-button><el-button type="primary" @click="saveLogistics">保存</el-button></template></el-dialog>
    <section v-if="readyToShip.length" class="section shipment-panel"><div class="section-title"><div><h2>确认发货</h2><span>仅可发货已完成标签确认的明细</span></div><el-button link type="primary" @click="selectAllReady">{{ allReadySelected ? '取消全选' : '整单选择待发货明细' }}</el-button></div><div v-for="line in readyToShip" :key="line.id" class="ship-line"><el-checkbox v-model="shipSelection[line.id].selected">{{ line.customer_part_no_snapshot }}</el-checkbox><el-input-number v-model="shipSelection[line.id].qty" :min="1" :max="line.remaining_qty" controls-position="right" /><span class="muted">剩余 {{ line.remaining_qty }}</span></div><div class="logistics-grid"><el-input v-model="shipmentForm.carrier" placeholder="物流公司" /><el-input v-model="shipmentForm.tracking" placeholder="物流号" /><el-button type="primary" @click="ship">确认已发货</el-button></div></section>
  </div>
</template>
<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { ElMessage, ElMessageBox } from 'element-plus'; import { cancelLine, cancellationConsent, confirmLabel, confirmShipment, getShippingHistory, getShippingOrder, submitShippingOrder, updateShipmentLogistics } from '@/api/shippingOrders'
const route = useRoute(); const router = useRouter(); const loading = ref(false); const order = ref<any>(null); const history = ref<any[]>([]); const shipSelection = reactive<Record<number, any>>({}); const shipmentForm = reactive({ carrier: '', tracking: '' }); const logisticsVisible = ref(false); const editingShipment = ref<any>(null); const logisticsEdit = ref<any[]>([])
const readyToShip = computed(() => (order.value?.lines || []).filter((line: any) => line.label_confirmed && line.remaining_qty > 0)); const allReadySelected = computed(() => readyToShip.value.length > 0 && readyToShip.value.every((line: any) => shipSelection[line.id]?.selected)); const formatDate = (value?: string) => value ? new Date(value).toLocaleString('zh-CN') : '-'; const lineLabel = (value: string) => ({ draft: '草稿', awaiting_label: '待标签', ready_to_ship: '待发货', partially_shipped: '部分发货', shipped: '已发货', cancelled: '已取消', partially_shipped_remaining_cancelled: '部分发货·剩余取消' } as any)[value] || value; const lineType = (value: string) => ({ ready_to_ship: 'success', shipped: 'success', cancelled: 'danger', partially_shipped: 'warning' } as any)[value] || 'info'; const latestConsent = (line: any) => (line.cancellation_consents || []).slice().sort((a: any, b: any) => b.id - a.id)[0]; const pendingConsent = (line: any) => latestConsent(line)?.status === 'pending'
const load = async () => { loading.value = true; try { const [nextOrder, nextHistory] = await Promise.all([getShippingOrder(Number(route.params.id)), getShippingHistory(Number(route.params.id))]); for (const line of nextOrder.lines || []) shipSelection[line.id] = shipSelection[line.id] || { selected: false, qty: line.remaining_qty }; order.value = nextOrder; history.value = nextHistory } catch (error: any) { ElMessage.error(error?.message || '订单加载失败') } finally { loading.value = false } }
const submit = async () => { try { await submitShippingOrder(order.value.id, {}); ElMessage.success('订单已提交'); await load() } catch (error: any) { const detail = error?.response?.data?.detail; if (detail?.code) { await ElMessageBox.confirm(detail.message, '提交提醒'); await submitShippingOrder(order.value.id, { confirm_duplicate_po: detail.code === 'DUPLICATE_CUSTOMER_PO', confirm_unregistered_customer_parts: detail.code === 'UNREGISTERED_CUSTOMER_PARTS' }); await load() } else ElMessage.error(detail || '提交失败') } }
const labelConfirm = async (line: any) => { await confirmLabel(line.id); ElMessage.success('标签已确认'); await load() }; const cancel = async (line: any) => { const reason = await ElMessageBox.prompt('请输入取消原因', '取消明细', { inputValidator: value => !!value?.trim() || '请输入原因' }); await cancelLine(line.id, { cancel_qty: line.remaining_qty, reason: reason.value }); ElMessage.success(line.label_confirmed ? '取消申请已记录，等待双方确认' : '明细已取消'); await load() }; const respondCancellation = async (line: any, consent: boolean) => { const item = latestConsent(line); if (!item) return; if (!consent) await ElMessageBox.confirm('拒绝后需重新发起取消申请，是否继续？', '拒绝取消'); await cancellationConsent(line.id, { consent }); ElMessage.success(consent ? '已记录取消确认' : '已拒绝取消申请'); await load() }
const editLogistics = (shipment: any) => { editingShipment.value = shipment; logisticsEdit.value = (shipment.logistics || []).map((item: any) => ({ carrier_name: item.carrier_name || '', tracking_no: item.tracking_no || '' })); logisticsVisible.value = true }
const saveLogistics = async () => { if (!editingShipment.value || !logisticsEdit.value.some(item => item.carrier_name || item.tracking_no)) return ElMessage.warning('至少填写物流公司或物流号'); await updateShipmentLogistics(editingShipment.value.id, { logistics: logisticsEdit.value }); ElMessage.success('物流信息已更新'); logisticsVisible.value = false; await load() }
const selectAllReady = () => { const selected = !allReadySelected.value; readyToShip.value.forEach((line: any) => { shipSelection[line.id] = { selected, qty: line.remaining_qty } }) }; const ship = async () => { const lines = readyToShip.value.filter((line: any) => shipSelection[line.id]?.selected).map((line: any) => ({ order_line_id: line.id, qty: shipSelection[line.id].qty })); if (!lines.length) return ElMessage.warning('请先选择要发货的明细'); if (!shipmentForm.carrier && !shipmentForm.tracking) return ElMessage.warning('至少填写物流公司或物流号'); try { await confirmShipment(order.value.id, { lines, logistics: [{ carrier_name: shipmentForm.carrier || null, tracking_no: shipmentForm.tracking || null }] }); ElMessage.success('发货已确认'); Object.assign(shipmentForm, { carrier: '', tracking: '' }); await load() } catch (error: any) { const detail = error?.response?.data?.detail; ElMessage.error(detail?.message || detail || error?.message || '发货失败') } }
onMounted(load)
</script>
<style scoped>
.detail-page { padding: 22px; }
.detail-head { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 16px; }
.detail-head h1 { margin: 4px 0; color: var(--zephyr-ink); font-size: 24px; }
.eyebrow { margin: 14px 0 0; color: var(--zephyr-primary); font-size: 12px; font-weight: 700; }
.subhead, .muted { color: #758188; font-size: 12px; }
.section { margin-top: 18px; padding: 16px; background: #fff; border: 1px solid #e0e6e4; }
.section-title { display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px; }
.section-title h2 { margin: 0; font-size: 16px; color: #304047; }
.section-title span { color: #7b878b; font-size: 12px; }
.ship-line { display: flex; align-items: center; gap: 18px; padding: 8px 0; border-bottom: 1px solid #edf0ef; }
.consent-hint { margin-top: 3px; color: #b7791f; font-size: 11px; }
.consent-hint.rejected { color: #b54b4b; }
.ship-line .el-input-number { margin-left: auto; }
.logistics-grid { display: grid; grid-template-columns: 1fr 1fr auto; gap: 8px; margin-top: 16px; }
.logistics-edit-row { display: grid; grid-template-columns: 1fr 1fr auto; gap: 8px; margin-bottom: 8px; }
@media (max-width: 700px) { .detail-head { flex-direction: column; gap: 12px; }.logistics-grid { grid-template-columns: 1fr; } }
</style>
